:- module(m__eu_procurement_shortlisting_citations, [implements/1, citation/2]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

citation(eu_dir_2014_24_art_65_1, [label - 'Directive 2014/24/EU, Article 65(1) (the power to limit the number of candidates, and the four procedures in which it exists)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'In restricted procedures, competitive procedures with negotiation, competitive dialogue procedures and innovation partnerships, contracting authorities may limit the number of candidates meeting the selection criteria that they will invite to tender or to conduct a dialogue, provided the minimum number, in accordance with paragraph 2, of qualified candidates is available.', units - ['02014L0024-20260101#parag_065.001']]).
citation(eu_dir_2014_24_art_65_2_indication, [label - 'Directive 2014/24/EU, Article 65(2) first sub-paragraph (what must be indicated in the contract notice or invitation to confirm interest)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The contracting authorities shall indicate, in the contract notice or in the invitation to confirm interest, the objective and non-discriminatory criteria or rules they intend to apply, the minimum number of candidates they intend to invite and, where appropriate, the maximum number.', units - ['02014L0024-20260101#parag_065.002']]).
citation(eu_dir_2014_24_art_65_2_minima, [label - 'Directive 2014/24/EU, Article 65(2) second sub-paragraph, first two sentences (the minimum is five in the restricted procedure and three in the other three)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'In the restricted procedure the minimum number of candidates shall be five. In the competitive procedure with negotiation, in the competitive dialogue procedure and in the innovation partnership the minimum number of candidates shall be three.', units - ['02014L0024-20260101#parag_065.002']]).
citation(eu_dir_2014_24_art_65_2_genuine_competition, [label - 'Directive 2014/24/EU, Article 65(2) second sub-paragraph, final sentence (sufficient to ensure genuine competition)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'In any event the number of candidates invited shall be sufficient to ensure genuine competition.', units - ['02014L0024-20260101#parag_065.002']]).
citation(eu_dir_2014_24_art_65_2_invitation_floor, [label - 'Directive 2014/24/EU, Article 65(2) third sub-paragraph, first sentence (invite at least the minimum number)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'The contracting authorities shall invite a number of candidates at least equal to the minimum number.', units - ['02014L0024-20260101#parag_065.002']]).
citation(eu_dir_2014_24_art_65_2_prohibition, [label - 'Directive 2014/24/EU, Article 65(2) third sub-paragraph, third sentence (the prohibition on including non-requesting operators or incapable candidates)', ref - 'http://publications.europa.eu/resource/celex/02014L0024-20260101.ENG.fmx4', verbatim - 'In the context of the same procedure, the contracting authority shall not include economic operators that did not request to participate, or candidates that do not have the required capabilities.', units - ['02014L0024-20260101#parag_065.002']]).

implements(Key) :-
    citation(Key, _).
